"use client";

import React, { useState } from 'react';
import { motion } from 'framer-motion';
import { Upload, Download, RefreshCw, CheckCircle, HelpCircle, FileText, Zap } from 'lucide-react';

export default function CompressTo20kb() {
    const [selectedImage, setSelectedImage] = useState<File | null>(null);
    const [compressedUrl, setCompressedUrl] = useState<string | null>(null);
    const [loading, setLoading] = useState(false);
    const [originalSize, setOriginalSize] = useState<number | null>(null);
    const [newSize, setNewSize] = useState<number | null>(null);

    const handleImageUpload = async (event: React.ChangeEvent<HTMLInputElement>) => {
        const file = event.target.files?.[0];
        if (file) {
            setSelectedImage(file);
            setOriginalSize(file.size);
            await compressOnServer(file);
        }
    };

    const compressOnServer = async (file: File) => {
        setLoading(true);
        try {
            const formData = new FormData();
            formData.append('file', file);
            formData.append('targetSize', '20');

            const response = await fetch('/api/compress', {
                method: 'POST',
                body: formData,
            });

            if (!response.ok) throw new Error('Compression failed');

            const blob = await response.blob();
            setCompressedUrl(URL.createObjectURL(blob));
            setNewSize(blob.size);
        } catch (error) {
            console.error("Compression failed:", error);
        } finally {
            setLoading(false);
        }
    };

    const downloadImage = () => {
        if (compressedUrl) {
            const link = document.createElement('a');
            link.href = compressedUrl;
            link.download = `smarttoolswala-compressed-20kb-${selectedImage?.name.split('.')[0]}.jpg`;
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);
        }
    };

    const reset = () => {
        setSelectedImage(null);
        setCompressedUrl(null);
        setOriginalSize(null);
        setNewSize(null);
    };

    return (
        <div className="min-h-screen pt-24 pb-12">
            <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    className="text-center"
                >
                    <h1 className="text-5xl font-extrabold mb-4 Sora">
                        Compress Image to <span className="blue-text inline">20kb</span>
                    </h1>
                    <p className="text-xl text-slate-400 max-w-3xl mx-auto mb-12">
                        Professional server-side compression using Sharp engine.
                        Perfectly optimized for UPSC, SSC, and banking portals.
                    </p>
                </motion.div>

                {/* Working Tool Area */}
                <div className="glass-card p-12 max-w-3xl mx-auto mb-24">
                    {!selectedImage ? (
                        <div
                            className="border-2 border-dashed border-white/10 rounded-2xl p-16 text-center cursor-pointer hover:border-blue-500/50 transition-colors"
                            onClick={() => document.getElementById('file-upload')?.click()}
                        >
                            <input
                                type="file"
                                id="file-upload"
                                accept="image/*"
                                className="hidden"
                                onChange={handleImageUpload}
                            />
                            <Upload className="w-16 h-16 text-blue-400 mx-auto mb-6" />
                            <h3 className="text-2xl font-bold mb-2">Upload Image to Compress</h3>
                            <p className="text-slate-500">JPG, PNG, WEBP (Maximum size 10MB)</p>
                        </div>
                    ) : (
                        <div>
                            <div className="grid grid-cols-2 gap-8 mb-12">
                                <div className="glass-card p-6 text-center">
                                    <p className="text-xs text-slate-500 uppercase tracking-widest mb-1">Original Size</p>
                                    <p className="text-2xl font-bold">{(originalSize! / 1024).toFixed(2)} KB</p>
                                </div>
                                <div className="glass-card p-6 text-center border-blue-500/30">
                                    <p className="text-xs text-slate-500 uppercase tracking-widest mb-1">Final Size</p>
                                    <p className="text-2xl font-bold text-cyan-400">
                                        {loading ? 'Processing...' : newSize ? `${(newSize / 1024).toFixed(2)} KB` : '--'}
                                    </p>
                                </div>
                            </div>

                            <div className="text-center space-x-4">
                                {loading ? (
                                    <div className="flex items-center justify-center gap-3 text-lg font-semibold">
                                        <RefreshCw className="spin text-blue-500" />
                                        <span>Sharp Engine Compressing...</span>
                                    </div>
                                ) : (
                                    <div className="flex flex-wrap gap-4 justify-center">
                                        <button className="btn-primary" onClick={downloadImage}>
                                            <Download className="w-5 h-5" /> Download 20kb Image
                                        </button>
                                        <button className="bg-white/5 border border-white/10 px-8 py-3 rounded-xl font-semibold hover:bg-white/10 transition-all" onClick={reset}>
                                            Start New
                                        </button>
                                    </div>
                                )}
                            </div>
                        </div>
                    )}
                </div>

                {/* SEO Section (Client-side rendered for now, will add Metadata later) */}
                <div className="mt-24 space-y-20">
                    <section className="text-center">
                        <h2 className="text-4xl font-bold mb-12 Sora">How the <span className="blue-text inline">20kb Compressor</span> Works</h2>
                        <div className="tools-grid">
                            <div className="glass-card p-10">
                                <div className="tool-icon mb-6"><CheckCircle /></div>
                                <h3 className="text-xl font-bold mb-3">1. Upload Photo</h3>
                                <p className="text-slate-400">Upload any JPG or PNG image you want to **compress to 20kb**. Our system handles high-res files easily.</p>
                            </div>
                            <div className="glass-card p-10">
                                <div className="tool-icon mb-6"><Zap /></div>
                                <h3 className="text-xl font-bold mb-3">2. Sharp Processing</h3>
                                <p className="text-slate-400">Our Node.js backend uses the industrial-grade **Sharp library** to perform lossy compression until target is reached.</p>
                            </div>
                            <div className="glass-card p-10">
                                <div className="tool-icon mb-6"><Download /></div>
                                <h3 className="text-xl font-bold mb-3">3. Instant Download</h3>
                                <p className="text-slate-400">As soon as the processing finishes, your **20kb image** is ready. Download without any email or signup.</p>
                            </div>
                        </div>
                    </section>

                    <article className="prose prose-invert max-w-4xl mx-auto">
                        <h2 className="text-3xl font-bold Sora text-white">Why use our Sharp-powered 20kb Image Reducer?</h2>
                        <p className="text-slate-400 text-lg leading-relaxed mt-6">
                            Unlike standard browser tools, our server-side engine ensures pixel-perfect quality even at ultra-low sizes. When you **compress image to 20kb online** with SmartToolsWala, you get scientific accuracy required for digital signatures and profile photos in government portals.
                        </p>
                        <div className="bg-blue-500/5 border border-blue-500/20 p-8 rounded-2xl my-10">
                            <h4 className="text-blue-400 font-bold mb-4">SEO FAQ: 20kb Compression</h4>
                            <div className="space-y-6">
                                <div>
                                    <p className="font-bold text-white uppercase text-xs tracking-widest">Question</p>
                                    <p className="text-white mt-1">Can I compress to exactly 20kb?</p>
                                    <p className="text-slate-400 mt-2">Yes, our algorithm iteratively adjusts quality levels to reach as close to 20kb (usually 18-20kb) as possible to ensure it's accepted by all portals.</p>
                                </div>
                                <div>
                                    <p className="font-bold text-white uppercase text-xs tracking-widest">Question</p>
                                    <p className="text-white mt-1">Is it safe to upload my photo?</p>
                                    <p className="text-slate-400 mt-2">Absolutely. Your images are only used for processing and are deleted from the server immediately after the conversation.</p>
                                </div>
                            </div>
                        </div>
                    </article>
                </div>
            </div>
        </div>
    );
}

"use client";

import React, { useState, useCallback } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
    Upload, Download, RefreshCw, CheckCircle2, XCircle,
    FileImage, Trash2, Zap, ShieldCheck, Clock, ImageIcon
} from 'lucide-react';

interface GenericCompressorClientProps {
    keyword: string;
    targetSizeKB: number;
    description: string;
    children?: React.ReactNode;
}

export default function GenericCompressorClient({ keyword, targetSizeKB, description, children }: GenericCompressorClientProps) {
    const [file, setFile] = useState<File | null>(null);
    const [optimizedUrl, setOptimizedUrl] = useState<string | null>(null);
    const [loading, setLoading] = useState(false);
    const [resultSize, setResultSize] = useState<number | null>(null);
    const [isDragging, setIsDragging] = useState(false);
    const [error, setError] = useState<string | null>(null);

    const compressImage = async (imgFile: File) => {
        setLoading(true);
        setError(null);
        try {
            const formData = new FormData();
            formData.append('file', imgFile);
            formData.append('targetSize', targetSizeKB.toString());
            const response = await fetch('/api/compress', { method: 'POST', body: formData });
            if (!response.ok) throw new Error('Compression failed');
            const blob = await response.blob();
            setOptimizedUrl(URL.createObjectURL(blob));
            setResultSize(blob.size);
        } catch (err) {
            setError('Something went wrong. Please try again.');
            console.error(err);
        } finally {
            setLoading(false);
        }
    };

    const handleFile = (selected: File) => {
        setFile(selected);
        setOptimizedUrl(null);
        setResultSize(null);
        compressImage(selected);
    };

    const handleUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
        const f = e.target.files?.[0];
        if (f) handleFile(f);
    };

    const handleDrop = useCallback((e: React.DragEvent) => {
        e.preventDefault();
        setIsDragging(false);
        const dropped = e.dataTransfer.files?.[0];
        if (dropped && dropped.type.startsWith('image/')) handleFile(dropped);
    }, []);

    const resetAll = () => { setFile(null); setOptimizedUrl(null); setResultSize(null); setError(null); };

    const resultKB = resultSize ? resultSize / 1024 : null;
    const isSuccess = resultKB !== null && resultKB <= targetSizeKB + 0.5;
    const saved = file && resultSize ? ((1 - resultSize / file.size) * 100).toFixed(0) : null;

    return (
        <div style={{ minHeight: '100vh', background: 'linear-gradient(160deg, #f8faff 0%, #f1f5ff 50%, #faf5ff 100%)', paddingBottom: '80px' }}>
            <div style={{ maxWidth: '860px', margin: '0 auto', padding: '110px 20px 0' }}>

                {/* ── Page Header ── */}
                <motion.div
                    initial={{ opacity: 0, y: 18 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ duration: 0.55, ease: [0.16, 1, 0.3, 1] }}
                    style={{ marginBottom: '32px' }}
                >
                    <span style={{
                        display: 'inline-flex', alignItems: 'center', gap: '6px',
                        background: 'linear-gradient(135deg, #ede9fe, #dbeafe)',
                        border: '1px solid #c4b5fd', borderRadius: '100px',
                        padding: '5px 14px', fontSize: '11px', fontWeight: 700,
                        color: '#5b21b6', letterSpacing: '0.04em', textTransform: 'uppercase',
                        marginBottom: '16px'
                    }}>
                        <Zap size={12} /> Free · No Signup · Instant
                    </span>

                    <h1 style={{
                        fontSize: 'clamp(28px, 5vw, 40px)', fontWeight: 800,
                        color: '#0f172a', lineHeight: 1.15, marginBottom: '12px',
                        letterSpacing: '-0.02em', textTransform: 'capitalize'
                    }}>
                        {keyword}
                    </h1>
                    <p style={{ fontSize: '16px', color: '#64748b', maxWidth: '520px', lineHeight: 1.65 }}>
                        {description}
                    </p>

                    {/* Trust pills */}
                    <div style={{ display: 'flex', flexWrap: 'wrap', gap: '8px', marginTop: '18px' }}>
                        {[
                            { icon: <ShieldCheck size={13} />, label: 'Files never stored' },
                            { icon: <Clock size={13} />, label: 'Under 3 seconds' },
                            { icon: <Zap size={13} />, label: '100% Free forever' },
                        ].map((p) => (
                            <span key={p.label} style={{
                                display: 'inline-flex', alignItems: 'center', gap: '5px',
                                background: '#ffffff', border: '1px solid #e2e8f0',
                                borderRadius: '100px', padding: '5px 12px',
                                fontSize: '12px', fontWeight: 600, color: '#475569',
                                boxShadow: '0 1px 3px rgba(0,0,0,0.06)'
                            }}>
                                <span style={{ color: '#7c3aed' }}>{p.icon}</span> {p.label}
                            </span>
                        ))}
                    </div>
                </motion.div>

                {/* ── Main Tool Card ── */}
                <motion.div
                    initial={{ opacity: 0, y: 24 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ duration: 0.55, delay: 0.08, ease: [0.16, 1, 0.3, 1] }}
                    style={{
                        background: '#ffffff',
                        borderRadius: '28px',
                        border: '1px solid #e8eaf0',
                        boxShadow: '0 4px 6px -1px rgba(0,0,0,0.05), 0 20px 60px -15px rgba(99,102,241,0.12)',
                        padding: '36px',
                        marginBottom: '20px'
                    }}
                >
                    <AnimatePresence mode="wait">
                        {!file ? (
                            /* ── Upload State ── */
                            <motion.div key="upload" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0, scale: 0.98 }}>
                                <div
                                    onClick={() => document.getElementById('file-input-main')?.click()}
                                    onDragOver={(e) => { e.preventDefault(); setIsDragging(true); }}
                                    onDragLeave={() => setIsDragging(false)}
                                    onDrop={handleDrop}
                                    style={{
                                        border: `2px dashed ${isDragging ? '#6366f1' : '#cbd5e1'}`,
                                        borderRadius: '20px',
                                        background: isDragging ? '#f5f3ff' : '#fafbff',
                                        padding: '52px 24px',
                                        textAlign: 'center',
                                        cursor: 'pointer',
                                        transition: 'all 0.2s ease',
                                        transform: isDragging ? 'scale(1.01)' : 'scale(1)',
                                    }}
                                >
                                    <input id="file-input-main" type="file" hidden accept="image/*" onChange={handleUpload} />

                                    {/* Icon container */}
                                    <div style={{
                                        width: '80px', height: '80px', borderRadius: '24px', margin: '0 auto 20px',
                                        background: 'linear-gradient(135deg, #ede9fe 0%, #dbeafe 100%)',
                                        display: 'flex', alignItems: 'center', justifyContent: 'center',
                                        boxShadow: '0 8px 24px rgba(99,102,241,0.15)',
                                        transition: 'transform 0.2s ease',
                                    }}>
                                        <Upload size={32} color="#5b21b6" strokeWidth={1.75} />
                                    </div>

                                    <p style={{ fontSize: '18px', fontWeight: 700, color: '#1e293b', marginBottom: '6px' }}>
                                        {isDragging ? 'Release to upload' : 'Drop your image here'}
                                    </p>
                                    <p style={{ fontSize: '14px', color: '#94a3b8', marginBottom: '24px' }}>
                                        or click anywhere to browse
                                    </p>

                                    <button style={{
                                        display: 'inline-flex', alignItems: 'center', gap: '8px',
                                        background: 'linear-gradient(135deg, #6366f1 0%, #8b5cf6 100%)',
                                        color: '#ffffff', border: 'none', borderRadius: '14px',
                                        padding: '13px 28px', fontSize: '14px', fontWeight: 700,
                                        cursor: 'pointer', letterSpacing: '0.01em',
                                        boxShadow: '0 4px 14px rgba(99,102,241,0.35)',
                                    }}>
                                        <ImageIcon size={16} /> Choose Image
                                    </button>
                                    <p style={{ fontSize: '12px', color: '#94a3b8', marginTop: '16px' }}>
                                        JPG · PNG · WEBP · Max 20 MB
                                    </p>
                                </div>
                            </motion.div>

                        ) : (
                            /* ── Result State ── */
                            <motion.div key="result" initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }}>

                                {/* File info bar */}
                                <div style={{
                                    display: 'flex', alignItems: 'center', justifyContent: 'space-between',
                                    background: '#f8faff', border: '1px solid #e0e7ff',
                                    borderRadius: '16px', padding: '12px 16px', marginBottom: '16px'
                                }}>
                                    <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                                        <div style={{
                                            width: '40px', height: '40px', borderRadius: '12px',
                                            background: '#ede9fe', display: 'flex', alignItems: 'center', justifyContent: 'center'
                                        }}>
                                            <FileImage size={20} color="#7c3aed" />
                                        </div>
                                        <div>
                                            <p style={{ fontSize: '13px', fontWeight: 700, color: '#1e293b', maxWidth: '220px', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
                                                {file.name}
                                            </p>
                                            <p style={{ fontSize: '12px', color: '#94a3b8' }}>
                                                Original size: {(file.size / 1024).toFixed(1)} KB
                                            </p>
                                        </div>
                                    </div>
                                    <button
                                        onClick={resetAll}
                                        style={{
                                            padding: '8px', borderRadius: '10px', border: '1px solid #fecdd3',
                                            background: '#fff1f2', color: '#f43f5e', cursor: 'pointer', display: 'flex'
                                        }}
                                    >
                                        <Trash2 size={16} />
                                    </button>
                                </div>

                                {/* Preview area */}
                                <div style={{
                                    position: 'relative', borderRadius: '16px', overflow: 'hidden',
                                    background: '#f8fafc', border: '1px solid #e2e8f0',
                                    minHeight: '220px', maxHeight: '420px',
                                    display: 'flex', alignItems: 'center', justifyContent: 'center',
                                    marginBottom: '16px'
                                }}>
                                    {loading && (
                                        <div style={{
                                            position: 'absolute', inset: 0, background: 'rgba(255,255,255,0.97)',
                                            display: 'flex', flexDirection: 'column', alignItems: 'center',
                                            justifyContent: 'center', gap: '16px', zIndex: 10
                                        }}>
                                            {/* Custom spinner */}
                                            <div style={{ position: 'relative', width: '64px', height: '64px' }}>
                                                <div style={{
                                                    position: 'absolute', inset: 0, borderRadius: '50%',
                                                    border: '3px solid #f1f5f9'
                                                }} />
                                                <div style={{
                                                    position: 'absolute', inset: 0, borderRadius: '50%',
                                                    border: '3px solid transparent',
                                                    borderTopColor: '#6366f1',
                                                    animation: 'spin 0.8s linear infinite'
                                                }} />
                                                <div style={{
                                                    position: 'absolute', inset: 0, display: 'flex',
                                                    alignItems: 'center', justifyContent: 'center'
                                                }}>
                                                    <Zap size={22} color="#6366f1" />
                                                </div>
                                            </div>
                                            <div style={{ textAlign: 'center' }}>
                                                <p style={{ fontSize: '15px', fontWeight: 700, color: '#1e293b' }}>Compressing image…</p>
                                                <p style={{ fontSize: '13px', color: '#94a3b8', marginTop: '4px' }}>Targeting {targetSizeKB} KB</p>
                                            </div>
                                        </div>
                                    )}
                                    {optimizedUrl && !loading && (
                                        // eslint-disable-next-line @next/next/no-img-element
                                        <img src={optimizedUrl} alt="Result" style={{ width: '100%', height: '100%', objectFit: 'contain', maxHeight: '400px' }} />
                                    )}
                                </div>

                                {/* Result badge */}
                                <AnimatePresence>
                                    {resultSize && !loading && (
                                        <motion.div
                                            initial={{ opacity: 0, y: 10, scale: 0.97 }}
                                            animate={{ opacity: 1, y: 0, scale: 1 }}
                                            style={{
                                                display: 'flex', alignItems: 'center', justifyContent: 'space-between',
                                                padding: '16px 20px', borderRadius: '16px', marginBottom: '16px',
                                                background: isSuccess ? 'linear-gradient(135deg, #f0fdf4, #dcfce7)' : 'linear-gradient(135deg, #fff1f2, #ffe4e6)',
                                                border: `1px solid ${isSuccess ? '#bbf7d0' : '#fecdd3'}`,
                                            }}
                                        >
                                            <div style={{ display: 'flex', alignItems: 'center', gap: '12px' }}>
                                                {isSuccess
                                                    ? <CheckCircle2 size={24} color="#16a34a" />
                                                    : <XCircle size={24} color="#e11d48" />
                                                }
                                                <div>
                                                    <p style={{ fontSize: '14px', fontWeight: 700, color: isSuccess ? '#14532d' : '#881337' }}>
                                                        {isSuccess
                                                            ? `Successfully compressed to ${resultKB!.toFixed(1)} KB`
                                                            : `Result is ${resultKB!.toFixed(1)} KB — above target`
                                                        }
                                                    </p>
                                                    <p style={{ fontSize: '12px', color: isSuccess ? '#16a34a' : '#e11d48', marginTop: '2px' }}>
                                                        {isSuccess
                                                            ? `${saved}% smaller than original · Under ${targetSizeKB} KB limit ✓`
                                                            : 'Try uploading a higher resolution source image'
                                                        }
                                                    </p>
                                                </div>
                                            </div>
                                            <span style={{
                                                fontSize: '22px', fontWeight: 800,
                                                color: isSuccess ? '#16a34a' : '#e11d48', letterSpacing: '-0.03em'
                                            }}>
                                                {resultKB!.toFixed(1)}<span style={{ fontSize: '13px', fontWeight: 600 }}>KB</span>
                                            </span>
                                        </motion.div>
                                    )}
                                </AnimatePresence>

                                {error && (
                                    <p style={{ textAlign: 'center', color: '#e11d48', fontSize: '13px', fontWeight: 600, marginBottom: '12px' }}>{error}</p>
                                )}

                                {/* Action buttons */}
                                <div style={{ display: 'flex', gap: '12px', flexWrap: 'wrap' }}>
                                    <button
                                        disabled={loading || !optimizedUrl}
                                        onClick={() => {
                                            const link = document.createElement('a');
                                            link.href = optimizedUrl!;
                                            link.download = `smarttoolswala-${targetSizeKB}kb-${file.name.split('.')[0]}.jpg`;
                                            link.click();
                                        }}
                                        style={{
                                            flex: 1, minWidth: '180px',
                                            display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '8px',
                                            background: loading || !optimizedUrl ? '#e2e8f0' : 'linear-gradient(135deg, #6366f1 0%, #8b5cf6 100%)',
                                            color: loading || !optimizedUrl ? '#94a3b8' : '#ffffff',
                                            border: 'none', borderRadius: '14px',
                                            padding: '14px 20px', fontSize: '15px', fontWeight: 700,
                                            cursor: loading || !optimizedUrl ? 'not-allowed' : 'pointer',
                                            boxShadow: loading || !optimizedUrl ? 'none' : '0 4px 14px rgba(99,102,241,0.35)',
                                            transition: 'all 0.2s ease',
                                        }}
                                    >
                                        <Download size={17} />
                                        Download {targetSizeKB}KB Image
                                    </button>
                                    <button
                                        onClick={resetAll}
                                        style={{
                                            display: 'flex', alignItems: 'center', justifyContent: 'center', gap: '8px',
                                            background: '#f8fafc', color: '#475569',
                                            border: '1px solid #e2e8f0', borderRadius: '14px',
                                            padding: '14px 20px', fontSize: '14px', fontWeight: 700,
                                            cursor: 'pointer', transition: 'all 0.2s ease', whiteSpace: 'nowrap'
                                        }}
                                    >
                                        <RefreshCw size={16} /> New Image
                                    </button>
                                </div>
                            </motion.div>
                        )}
                    </AnimatePresence>
                </motion.div>

                {/* ── How to Use ── */}
                <motion.div
                    initial={{ opacity: 0, y: 20 }}
                    animate={{ opacity: 1, y: 0 }}
                    transition={{ duration: 0.5, delay: 0.15 }}
                    style={{
                        background: '#ffffff', borderRadius: '24px',
                        border: '1px solid #e8eaf0',
                        boxShadow: '0 2px 20px rgba(0,0,0,0.04)',
                        padding: '28px 32px', marginBottom: '24px'
                    }}
                >
                    <h2 style={{ fontSize: '16px', fontWeight: 800, color: '#0f172a', marginBottom: '20px', letterSpacing: '-0.01em' }}>
                        How it works
                    </h2>
                    <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(180px, 1fr))', gap: '16px' }}>
                        {[
                            { n: '01', title: 'Upload Image', desc: 'Click or drag & drop JPG, PNG, or WEBP', color: '#6366f1' },
                            { n: '02', title: 'Auto Compress', desc: `Compressed to exactly ${targetSizeKB}KB instantly`, color: '#8b5cf6' },
                            { n: '03', title: 'Download', desc: 'Preview & download your optimized image', color: '#0ea5e9' },
                        ].map((s) => (
                            <div key={s.n} style={{
                                padding: '18px', borderRadius: '16px',
                                background: '#f8faff', border: '1px solid #eff0f7',
                                display: 'flex', flexDirection: 'column', gap: '10px'
                            }}>
                                <span style={{
                                    width: '38px', height: '38px', borderRadius: '12px',
                                    background: s.color, color: '#fff',
                                    display: 'flex', alignItems: 'center', justifyContent: 'center',
                                    fontSize: '13px', fontWeight: 800, letterSpacing: '-0.01em',
                                    boxShadow: `0 4px 10px ${s.color}44`
                                }}>
                                    {s.n}
                                </span>
                                <div>
                                    <p style={{ fontSize: '14px', fontWeight: 700, color: '#1e293b', marginBottom: '4px' }}>{s.title}</p>
                                    <p style={{ fontSize: '12px', color: '#94a3b8', lineHeight: 1.55 }}>{s.desc}</p>
                                </div>
                            </div>
                        ))}
                    </div>
                </motion.div>

                {/* SEO / FAQ children */}
                {children}
            </div>
        </div>
    );
}
